def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Find the largest 4-connected component of each color.
    largest = defaultdict(int)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            size = 0
            for y, x in q:
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            largest[color] = max(largest[color], size)

    # Tiny disconnected colors are stray pixels; restore them from neighboring shapes.
    stray = {color for color, size in largest.items() if size <= 2}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in stray:
                continue
            neighbors = Counter()
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if not (dy or dx):
                        continue
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w:
                        color = grid[y][x]
                        if color != bg and color not in stray:
                            neighbors[color] += 1
            out[r][c] = neighbors.most_common(1)[0][0] if neighbors else bg
    return out
